update public.lessons as lesson
set
  title = program.title,
  description = program.description,
  content_md = program.content_md,
  homework_md = program.homework_md
from (
  values
    (
      1,
      'Что такое тестирование',
      'Знакомство с профессией QA и базовыми понятиями.',
      E'## Что такое тестирование\n\nТестирование помогает понять, соответствует ли продукт требованиям и ожиданиям пользователя. Его цель - не доказать отсутствие ошибок, а вовремя заметить риски и сообщить о них команде.\n\n### Кто такой QA Engineer\n\nQA Engineer заботится о качестве на всём пути задачи: читает требования, составляет проверки, тестирует функциональность, фиксирует дефекты и обсуждает результат с командой.\n\n### Базовые понятия\n\n- **Качество** - насколько продукт решает задачу пользователя и соответствует договорённостям.\n- **Тестирование** - проверка продукта и поиск информации о его качестве.\n- **Дефект (баг)** - несоответствие фактического результата ожидаемому.\n\nQA не ищет виноватых. Его задача - помочь команде выпустить понятный и надёжный продукт.',
      E'Выбери знакомое приложение. Опиши одну его функцию, ожидание пользователя от неё и одну проверку, которую проведёт QA.'
    ),
    (
      2,
      'Как работает IT-команда',
      'Роли в команде, взаимодействие участников и место QA.',
      E'## Как работает IT-команда\n\nПродукт создают вместе. У каждого участника своя зона ответственности, но качество зависит от того, как команда договаривается и передаёт задачу дальше.\n\n### Основные роли\n\n- **Product Owner / Product Manager** определяет цель и приоритет задачи.\n- **Аналитик** уточняет требования и сценарии.\n- **Дизайнер** проектирует пользовательский опыт и интерфейс.\n- **Разработчик** реализует решение.\n- **QA Engineer** проверяет требования и готовый результат, сообщает о рисках.\n\n### Путь задачи\n\nИдея превращается в требования, затем в дизайн и разработку. После этого QA проверяет функциональность, команда исправляет найденные проблемы и выпускает релиз. QA подключается раньше тестирования: хорошие вопросы к требованиям экономят время всей команды.',
      E'Составь путь задачи «Пользователь меняет пароль»: кто и что делает на каждом этапе от идеи до релиза. Отдельно укажи, в какой момент подключается QA.'
    ),
    (
      12,
      'Методологии разработки',
      'Waterfall, Agile, Scrum, Kanban: как устроены и чем отличаются.',
      E'## Методологии разработки\n\nМетодология помогает команде организовать работу: понять, что делать, когда обсуждать результат и как быстро реагировать на изменения.\n\n### Waterfall\n\nЭтапы идут последовательно: требования, дизайн, разработка, тестирование, релиз. Подходит, когда требования стабильны, но изменения в конце обходятся дорого.\n\n### Agile\n\nAgile - гибкий подход: команда выпускает продукт небольшими частями, регулярно получает обратную связь и корректирует план.\n\n### Scrum\n\nScrum - один из Agile-фреймворков. Работа идёт короткими спринтами с планированием, ежедневными синхронизациями, демонстрацией результата и ретроспективой.\n\n### Kanban\n\nKanban визуализирует поток задач на доске и ограничивает количество задач в работе. Это помогает быстрее замечать блокировки и не перегружать команду.\n\nQA следит за задачами, уточняет критерии готовности и сообщает о качестве до релиза.',
      E'Сравни Scrum и Kanban в 3-5 пунктах. Затем напиши, на каких этапах QA должен подключаться к задаче в Scrum.'
    ),
    (
      13,
      'Твой первый день QA',
      'Получаем реальную QA-задачу и тестируем на учебном стенде.',
      E'## Твой первый день QA\n\nТы получаешь задачу от аналитика и доступ к учебному стенду. Теперь нужно пройти путь QA от понимания задачи до понятного результата для команды.\n\n### Твой план работы\n\n1. Прочитай описание задачи и задай вопросы по неясным условиям.\n2. Составь чек-лист основных и пограничных проверок.\n3. Протестируй сценарий на стенде.\n4. Используй DevTools, чтобы посмотреть ошибки и запросы.\n5. При необходимости проверь API в Postman и данные SQL-запросом.\n6. Оформи найденные дефекты: шаги, expected, actual, Severity и Priority.\n7. Подведи итог: что проверено, что найдено, какие риски остались.\n\nЭто учебная симуляция реальной работы. Главное - действовать последовательно и фиксировать наблюдения.',
      E'Выполни сквозную задачу: составь чек-лист минимум из 10 проверок для формы регистрации, опиши 2 баг-репорта и укажи, что проверишь через DevTools, API и SQL.'
    )
) as program(day_number, title, description, content_md, homework_md)
where lesson.day_number = program.day_number;
